<?php
namespace App\Services;use App\Models\{Debt,Payment,PaymentAllocation,CreditBalance,CashboxTransaction};use Illuminate\Support\Facades\DB;
class SettlementService{public function settle(Payment $payment):void{DB::transaction(function()use($payment){$remaining=$payment->amount;$debts=Debt::where('account_id',$payment->account_id)->where('currency_id',$payment->currency_id)->where('remaining_amount','>',0)->orderBy('issue_date')->orderBy('id')->lockForUpdate()->get();foreach($debts as $debt){if($remaining<=0)break;$amount=min($remaining,$debt->remaining_amount);PaymentAllocation::create(['organization_id'=>$payment->organization_id,'payment_id'=>$payment->id,'debt_id'=>$debt->id,'allocated_amount'=>$amount]);$debt->remaining_amount-=$amount;$debt->status=$debt->remaining_amount<=0?'paid':'partially_paid';$debt->save();$remaining-=$amount;}if($remaining>0){CreditBalance::updateOrCreate(['organization_id'=>$payment->organization_id,'account_id'=>$payment->account_id,'currency_id'=>$payment->currency_id],['amount'=>DB::raw('amount + '.$remaining)]);}CashboxTransaction::create(['organization_id'=>$payment->organization_id,'transaction_type'=>'payment_received','amount'=>$payment->amount,'currency_id'=>$payment->currency_id,'reference_type'=>Payment::class,'reference_id'=>$payment->id,'created_by'=>$payment->created_by]);});}}
class CreditBalanceService{public function consume(Debt $debt):void{DB::transaction(function()use($debt){$credit=CreditBalance::where(['account_id'=>$debt->account_id,'currency_id'=>$debt->currency_id])->lockForUpdate()->first();if(!$credit||$credit->amount<=0)return;$used=min($credit->amount,$debt->remaining_amount);$credit->amount-=$used;$credit->save();$debt->remaining_amount-=$used;$debt->status=$debt->remaining_amount<=0?'paid':'partially_paid';$debt->save();});}}
